"""Safely extract plain-data structure from a pickle without executing it.

Walks pickle opcodes via pickletools and builds the object graph using only
data opcodes. Globals are never imported and callables are never invoked:
STACK_GLOBAL yields a sentinel, and REDUCE on a sentinel yields a sentinel.
"""
import pickletools

class BlockedGlobal:
    def __init__(self, name):
        self.name = name
    def __repr__(self):
        return f"<blocked global {self.name}>"

class BlockedResult:
    def __repr__(self):
        return "<blocked reduce result>"

def safe_load(path):
    with open(path, "rb") as f:
        data = f.read()
    stack, memo, mark = [], {}, object()
    for opcode, arg, pos in pickletools.genops(data):
        n = opcode.name
        if n in ("PROTO", "FRAME"):
            continue
        elif n == "STOP":
            return stack[-1]
        elif n == "MARK":
            stack.append(mark)
        elif n in ("SHORT_BINUNICODE", "BINUNICODE", "UNICODE",
                   "SHORT_BINBYTES", "BINBYTES", "BYTEARRAY8",
                   "BININT", "BININT1", "BININT2", "INT", "LONG", "LONG1", "LONG4",
                   "BINFLOAT", "FLOAT", "NONE", "NEWTRUE", "NEWFALSE"):
            stack.append(arg if n not in ("NONE", "NEWTRUE", "NEWFALSE")
                         else {"NONE": None, "NEWTRUE": True, "NEWFALSE": False}[n])
        elif n in ("EMPTY_DICT",):
            stack.append({})
        elif n in ("EMPTY_LIST",):
            stack.append([])
        elif n in ("EMPTY_TUPLE", "EMPTY_SET", "FROZENSET") and n != "FROZENSET":
            stack.append(() if n == "EMPTY_TUPLE" else set())
        elif n in ("MEMOIZE",):
            memo[len(memo)] = stack[-1]
        elif n in ("BINPUT", "LONG_BINPUT"):
            memo[arg] = stack[-1]
        elif n in ("BINGET", "LONG_BINGET", "GET"):
            stack.append(memo[arg])
        elif n in ("APPEND",):
            v = stack.pop(); stack[-1].append(v)
        elif n in ("APPENDS",):
            items = []
            while stack[-1] is not mark: items.append(stack.pop())
            stack.pop()
            stack[-1].extend(reversed(items))
        elif n in ("SETITEM",):
            v = stack.pop(); k = stack.pop(); stack[-1][k] = v
        elif n in ("SETITEMS",):
            items = []
            while stack[-1] is not mark: items.append(stack.pop())
            stack.pop()
            d = stack[-1]
            items.reverse()
            for i in range(0, len(items), 2):
                d[items[i]] = items[i + 1]
        elif n in ("TUPLE1", "TUPLE2", "TUPLE3"):
            k = int(n[-1])
            stack[-k:] = [tuple(stack[-k:])]
        elif n in ("TUPLE",):
            items = []
            while stack[-1] is not mark: items.append(stack.pop())
            stack.pop()
            stack.append(tuple(reversed(items)))
        elif n in ("GLOBAL", "STACK_GLOBAL"):
            if n == "GLOBAL":
                name = arg
            else:
                name = f"{stack.pop()}.{stack.pop()}"[::-1].replace(".", "/", 1)[::-1]
                # STACK_GLOBAL pops name then module
            stack.append(BlockedGlobal(str(arg) if n == "GLOBAL" else name))
        elif n in ("REDUCE",):
            args = stack.pop(); fn = stack.pop()
            if isinstance(fn, BlockedGlobal) or isinstance(fn, BlockedResult):
                stack.append(BlockedResult())
            else:
                raise ValueError(f"Refusing to REDUCE callable {fn!r} at {pos}")
        elif n in ("BUILD", "INST", "OBJ", "NEWOBJ", "NEWOBJ_EX", "PERSID",
                   "BINPERSID", "EXT1", "EXT2", "EXT4"):
            raise ValueError(f"Refusing dangerous opcode {n} at offset {pos}")
        else:
            raise ValueError(f"Unhandled opcode {n} at offset {pos}")
    raise ValueError("No STOP opcode found")

if __name__ == "__main__":
    import json, sys
    d = safe_load(sys.argv[1])
    print(json.dumps(d, default=repr, indent=2))
